function validate([seats, students]) {
  if (!Array.isArray(seats) || !Array.isArray(students)) return 'seats and students must be arrays.';
  if (seats.length !== students.length) return 'seats and students must have the same length.';
  if (seats.length < 1 || seats.length > 100) return 'There must be 1 to 100 seats.';
  if ([...seats, ...students].some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Every position is an integer from 1 to 100.';
  return null;
}

