function minMovesToSeat(seats, students) {
  // Try every assignment of students to seats (a permutation) and keep the cheapest.
  const n = seats.length;
  const used = new Array(n).fill(false);
  let best = Infinity;
  const place = (j, cost) => {
    if (cost >= best) return;
    if (j === n) { best = cost; return; }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      place(j + 1, cost + Math.abs(seats[i] - students[j]));
      used[i] = false;
    }
  };
  place(0, 0);
  return best;
}

